<script setup lang="ts">
import {ref} from 'vue'
import {session} from '../api'
import {clearRecovery} from '../storage'
const current=ref(''),password=ref(''),confirmPassword=ref(''),busy=ref(false),error=ref('')
async function changePassword(){error.value='';if([...password.value].length<15||[...password.value].length>1024||new TextEncoder().encode(password.value).length>4096){error.value='新密码需为 15–1024 个字符，且不超过 4096 字节。';return}if(password.value!==confirmPassword.value){error.value='两次输入的新密码不一致，请重新确认。';return}busy.value=true;try{const response=await fetch('/api/v1/me/password',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf_token},body:JSON.stringify({current_password:current.value,new_password:password.value})});if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.error?.message||'密码未修改，请检查当前密码后重试。')}await clearRecovery(session.user.id).catch(()=>{});location.assign('/login?password_changed=1')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><form class="panel password-panel" @submit.prevent="changePassword"><h2>修改登录密码</h2><p class="muted">修改后所有设备会退出登录。请先确认草稿已同步，或导出本地内容。</p><p class="muted">若账号仅使用 GitHub 登录，请联系管理员初始化本地密码。</p><div v-if="error" class="notice error" role="alert">{{error}}</div><div class="form-grid"><label class="full">当前密码<input v-model="current" type="password" required autocomplete="current-password"></label><label>新密码<input v-model="password" type="password" required autocomplete="new-password" aria-describedby="password-policy"></label><label>确认新密码<input v-model="confirmPassword" type="password" required autocomplete="new-password"></label></div><p id="password-policy" class="muted">15–1024 个字符。可以使用长短语，首尾空格会保留。</p><div class="form-actions"><button class="primary" :disabled="busy">{{busy?'正在修改…':'修改密码并退出登录'}}</button></div></form></template>
